// Simular temperatura (ej. 15 a 35) y humedad (ej. 40 a 90)
var temp = Math.floor(Math.random() * (35 - 15 + 1)) + 15;
var hum = Math.floor(Math.random() * (90 - 40 + 1)) + 40;

// Construir la URL dinámicamente. Cambia localhost por tu IP si es necesario.
msg.url = "http://localhost:1880/sensores/" + temp + "/" + hum;

return msg;

var temp = msg.req.params.temp;
var hum = msg.req.params.hum;

// Enviar temperatura por la salida 1 y humedad por la salida 2
return [{ payload: temp }, { payload: hum }];

// Genera un valor aleatorio entre 1.0 y 15.0
let valor_dinamico = (Math.random() * (15.0 - 1.0) + 1.0).toFixed(1);

msg.payload = {
  "sistema": "Monitoreo Energético",
  "consumo_kwh": parseFloat(valor_dinamico),
  "unidad": "kWh"
};
return msg;

// Respuesta estática de ubicación
msg.payload = {
  "laboratorio": "Laboratorio de Redes",
  "bloque": "Bloque de Ingeniería"
};
return msg;

// Generación de un valor dinámico en el rango sugerido (1.0 a 15.0 kWh)
const consumo = parseFloat((Math.random() * (15.0 - 1.0) + 1.0).toFixed(1));

msg.payload = {
    "sistema": "Monitoreo Energético",
    "consumo_kwh": consumo,
    "unidad": "kWh"
};

msg.statusCode = 200;
return msg;

// Retorno de información de laboratorio y bloque
msg.payload = {
    "laboratorio": "Laboratorio de Redes",
    "bloque": "Bloque de Ingeniería"
};

msg.statusCode = 200;
return msg;

var msgTemp = { payload: Number(msg.req.params.temp) };
var msgHum = { payload: Number(msg.req.params.hum) };
return [msgTemp, msgHum];
